H('402.d.3.D',4,"A short question that needs a quick answer is best sent by:","a chat message",["a formal report","a poster","a letter by mail"],"Match the format to the need.")
H('402.d.3.E',3,"A good first step in solving a problem is to:","define it clearly",["guess","ignore it","blame someone"],"Defining the problem guides action.")
H('402.d.3.E',4,"Breaking a problem into smaller parts to solve is a strategy known as:","decomposition",["avoidance","repetition","delay"],"Decompose complex problems.")
H('402.d.4.A',3,"Employers are responsible for providing a workplace that is:","reasonably safe and free from known hazards",["fun","always quiet","rent-free"],"Employers must provide safe workplaces.")
H('402.d.4.A',4,"Workers have the responsibility to follow safety rules and to:","report hazards and unsafe conditions",["ignore warnings","hide injuries","skip training"],"Workers help keep the site safe.")
H('402.d.4.B',3,"Industrial hygiene focuses on recognizing and controlling workplace:","health hazards",["pay rates","uniforms","vacations"],"Industrial hygienists protect worker health.")
H('402.d.4.B',4,"Measuring noise, dust, and chemical levels at a plant is the work of:","industrial hygiene",["marketing","sales","payroll"],"Hygiene measures exposures.")
H('402.d.4.C',3,"Hearing protection is worn to protect the ears from:","loud noise",["bright light","cold","wind"],"Earplugs and muffs reduce noise.")
H('402.d.4.C',4,"The best personal protective equipment for grinding metal includes:","safety glasses or a face shield",["sandals","bare hands","sunglasses only"],"Sparks require eye and face protection.")
H('402.d.4.D',3,"To prevent trips in a shop, walkways should be kept:","clear of cords and clutter",["narrow","dark","wet"],"Clear paths prevent falls.")
H('402.d.4.D',4,"A spill on a shop floor should be:","cleaned up immediately or marked with a warning sign",["left until later","ignored","walked around quickly"],"Wet floors cause slips.")
H('402.d.4.E',3,"Water and electricity together are dangerous because water:","conducts electricity",["blocks it","absorbs it harmlessly","stops current"],"Water creates shock paths.")
H('402.d.4.E',4,"A ground fault circuit interrupter (GFCI) protects people by:","shutting off power when it detects leakage current",["increasing voltage","blocking all current","cooling wires"],"GFCIs trip quickly.")
H('402.d.4.F',3,"An emergency action plan includes exit routes and:","assembly points",["menu choices","sale prices","uniform colors"],"Everyone should know where to go.")
H('402.d.4.F',4,"Safety Data Sheets are a workplace resource that provide information on a chemical's:","hazards and safe handling",["price","color","owner"],"SDS describe hazards.")
H('402.d.5.A',3,"An engineering notebook is valuable because it can serve as a:","legal record of ideas and work",["music diary","grocery list","game log"],"Notebooks help prove dates of invention.")
H('402.d.5.A',4,"Entries in an engineering notebook should be dated and signed so the notebook can:","help prove who invented something and when",["be erased easily","be hidden","replace patents"],"Dates and signatures establish authorship.")
H('402.d.5.B',3,"In an engineering notebook, mistakes should be:","crossed out with a single line",["torn out","erased fully","covered in correction fluid"],"Original entries must remain visible.")
H('402.d.5.B',4,"Pages in a bound engineering notebook are numbered so that:","missing pages can be detected",["pages look nicer","ink is saved","covers match"],"Numbered pages protect integrity.")
H('402.d.5.C',3,"A notebook entry should include sketches, notes, and:","data and observations",["jokes","gossip","unrelated drawings"],"Record what you did and saw.")
H('402.d.5.C',4,"Taping a printed test graph into the notebook and labeling it is a way to:","keep results with their context",["avoid analysis","hide data","reduce records"],"Attach and label evidence.")
H('402.d.5.D',3,"Teams should report progress at:","regular intervals",["random times only","the very end only","never"],"Regular updates keep projects on track.")
H('402.d.5.D',4,"A weekly status report to a supervisor should list work completed, work planned, and:","problems or delays",["lunch orders","personal news","weather"],"Reports flag issues early.")
H('402.d.6.A',3,"An emerging technology such as artificial intelligence can offer faster analysis but also raises concerns about:","privacy and job changes",["paper cost","pencil lead","chairs"],"New technology has trade-offs.")
H('402.d.6.A',4,"Weighing the advantages and disadvantages of a new technology before using it is part of making a:","responsible decision",["random choice","hasty purchase","guess"],"Evaluate before adopting.")
H('402.d.6.B',3,"Combining information from several reliable sources is called:","synthesizing",["copying","guessing","erasing"],"Synthesis builds a complete picture.")
H('402.d.6.B',4,"When two sources disagree, a researcher should:","check additional reliable sources",["pick the shorter one","ignore both","use the first one found"],"Verify with more evidence.")
H('402.d.6.C',3,"Downloading music or software without permission is:","unethical and often illegal",["acceptable","free sharing","best practice"],"Respect others' rights.")
H('402.d.6.C',4,"Using someone else's image in a presentation requires:","permission or a proper license",["no credit","a different color","hiding the source"],"Use content legally.")
H('402.d.6.D',3,"A citation tells readers:","where information came from",["the cost","the time","the color"],"Citations credit sources.")
H('402.d.6.D',4,"Copying a paragraph word for word without credit is:","plagiarism",["research","paraphrasing","synthesis"],"Plagiarism is using others' work as your own.")
H('402.d.6.E',3,"A patent protects a new:","invention",["name","song lyric","book cover"],"Patents cover inventions.")
H('402.d.6.E',4,"A copyright protects:","original creative works such as software code or writing",["inventions","brand names only","ideas without form"],"Copyright covers expression.")
H('402.d.6.F',3,"A source that is out of date may give information that is:","no longer accurate",["more precise","always correct","permanent"],"Check publication dates.")
H('402.d.6.F',4,"A source that stands to profit from a claim may show:","bias",["certainty","neutrality","proof"],"Consider the author's interests.")
H('402.d.7.A',3,"A good problem statement tells who has the problem, what the problem is, and:","why it matters",["what color to use","when lunch is","who the mascot is"],"Statements give context and importance.")
H('402.d.7.A',4,"The statement 'Wheelchair users cannot reach top shelves in the school library' names the:","people affected and the problem",["materials","budget","schedule"],"It identifies who and what.")
H('402.d.7.B',3,"One method to refine a problem statement is to:","interview users",["guess","hide it","copy another"],"User input sharpens focus.")
H('402.d.7.B',4,"Asking 'why' repeatedly to reach the root cause of a problem is known as the:","five whys technique",["five senses test","random walk","trial and error only"],"Repeated why finds root causes.")
H('402.d.7.C',3,"A measurable problem statement includes:","a number or limit that can be tested",["a feeling","a color only","a name"],"Measurable means testable.")
H('402.d.7.C',4,"Which statement is most specific and measurable?","Reduce backpack weight to under 10 pounds for ninth graders.",["Make better backpacks.","Backpacks are heavy.","Students carry things."],"It states a target and group.")
H('402.d.7.D',3,"After writing a problem statement, a team should collect:","information that helps to understand the problem",["unrelated data","only opinions","nothing"],"Gather relevant data.")
H('402.d.7.D',4,"Survey data from 50 students shows most carry over 15 pounds. This information helps the team to:","confirm the need",["end the project","raise the price","pick a color"],"Data supports the problem.")
H('402.d.7.E',3,"New information may require the team to:","revise the problem statement",["ignore it","erase notes","stop"],"Statements evolve.")
H('402.d.7.E',4,"If testing shows that users care more about comfort than weight, the team should:","modify the statement to include comfort",["keep it unchanged","blame users","hide the data"],"Update with learning.")
H('402.d.7.F',3,"A design brief is a document that outlines the:","problem, goals, and constraints of a project",["lunch menu","seating chart","game rules"],"Briefs define the project.")
H('402.d.7.F',4,"A design brief helps a team stay on track by describing the:","requirements the solution must meet",["team members' hobbies","company logo","weather"],"Requirements guide design.")
H('402.d.7.G',3,"A technical document should include a problem statement, constraints, and:","criteria for success",["jokes","menus","slogans"],"Criteria define success.")
H('402.d.7.G',4,"A well-compiled design brief is written so that a new team member can:","understand the project without extra explanation",["do nothing","guess the goal","need a translator"],"Clear documents stand alone.")
H('402.d.8.A',3,"Creativity in engineering helps teams to:","find new solutions to problems",["avoid thinking","copy exactly","repeat errors"],"Creativity drives innovation.")
H('402.d.8.A',4,"Innovation differs from invention because innovation:","puts a new idea to practical, valuable use",["is always a physical device","requires a patent","is always small"],"Innovation applies ideas.")
H('402.d.8.B',3,"In brainstorming, a rule is to:","withhold judgment while ideas are generated",["criticize every idea","stay silent","pick one idea only"],"Defer judgment.")
H('402.d.8.B',4,"SCAMPER is a technique that prompts new ideas by asking how to substitute, combine, adapt, modify, put to other uses, eliminate, or:","reverse",["delete files","repeat","cancel"],"R is rearrange or reverse.")
H('402.d.8.C',3,"Designing a product for a client differs from designing for oneself because the designer must meet the:","client's needs",["designer's whims only","random tastes","calendar"],"Clients define requirements.")
H('402.d.8.C',4,"When a client's wishes conflict with safety, the engineer should:","explain the risk and propose a safe alternative",["ignore safety","do as told","quit silently"],"Safety remains non-negotiable.")
H('402.d.8.D',3,"A solution can be evaluated with criteria such as strength, cost, and:","ease of manufacture",["the team's color","the date","the song"],"Evaluate with relevant criteria.")
H('402.d.8.D',4,"Comparing two bracket designs by testing which holds the heavier load is an evaluation of:","structural strength",["appearance","name","weight of the box"],"Load tests measure strength.")
H('402.d.8.E',3,"Capturing client feedback helps a team to:","refine the solution to better meet the need",["avoid changes","hide flaws","end the project"],"Feedback improves fit.")
H('402.d.8.E',4,"Showing a client an early prototype is helpful because it allows the client to:","react before time and money are spent on final production",["buy it","keep it","tell others"],"Early feedback saves cost.")
H('402.d.8.F',3,"One way to gather end-user input is a:","survey",["guess","lecture","poster"],"Surveys collect user opinions.")
H('402.d.8.F',4,"Watching users interact with a product to see where they struggle is called:","observation",["advertising","manufacturing","debugging"],"Observation reveals real behavior.")
H('402.d.9.A',3,"Freehand sketching is useful early in design because it is:","quick and requires no special tools",["slow","costly","exact"],"Sketches capture ideas fast.")
H('402.d.9.A',4,"A technical drawing is used when the team needs to communicate:","exact sizes and details for making a part",["a rough idea only","a mood","a slogan"],"Technical drawings are precise.")
H('402.d.9.B',3,"A nontechnical sketch of a phone holder is made mostly to show:","the general idea of the shape",["exact tolerances","material grades","cost"],"Rough drawings communicate concepts.")
H('402.d.9.B',4,"A cardboard mock-up of a product is an example of a:","simple physical model",["final product","patent","specification"],"Mock-ups explore form cheaply.")
H('402.d.9.C',3,"A technical model of a solution can be developed from a sketch by adding:","dimensions and specifications",["jokes","colors only","music"],"Models add precision.")
H('402.d.9.C',4,"Turning a sketch into a 3D computer model requires choosing:","sizes and units for each feature",["a mascot","a soundtrack","a slogan"],"Digital models need dimensions.")
H('402.d.9.D',3,"A multi-view projection shows an object from the front, top, and:","side",["inside only","price","corner of the room"],"Standard views include the right side.")
H('402.d.9.D',4,"A single-view pictorial drawing that shows three faces of a cube at once is an:","isometric drawing",["orthographic view","section view","floor plan"],"Isometric shows three faces.")
H('402.d.10.A',3,"A prototype is an early version of a design used to:","test and improve ideas",["sell widely","replace the plan","impress friends only"],"Prototypes help learning.")
H('402.d.10.A',4,"A prototype that tests only how a product looks, not how it works, is called a:","visual or appearance prototype",["functional prototype","patent","final product"],"Different prototypes test different things.")
H('402.d.10.B',3,"Before building a prototype, a team should have:","a plan and a list of materials",["no drawings","random parts","a finished product"],"Prototyping needs planning.")
H('402.d.10.B',4,"A step-by-step build plan for a prototype reduces:","wasted materials and rework",["testing","feedback","drawings"],"Plans prevent waste.")
H('402.d.10.C',3,"Choosing the right tool for a task helps to:","get accurate results safely",["break parts","slow down","waste material"],"Right tools improve quality and safety.")
H('402.d.10.C',4,"A 3D printer is well suited for making a prototype with:","complex shapes that are hard to machine",["only flat sheets","no material","nothing"],"Additive manufacturing builds complex forms.")
H('402.d.10.D',3,"Presentation software can be used to show a prototype using photos, diagrams, and:","test results",["jokes only","blank slides","unrelated art"],"Slides communicate evidence.")
H('402.d.10.D',4,"A clear prototype presentation tells the audience the problem, the solution, and:","how it performed",["the team's snacks","the room temperature","the school bus route"],"Results close the story.")
H('402.d.11.A',3,"Testing a prototype is done to find out whether it:","works as intended",["is pretty","is cheap to throw away","is famous"],"Tests verify function.")
H('402.d.11.A',4,"Finding a flaw in a prototype test is useful because it:","shows what to improve before final production",["wastes time","proves the design is perfect","ends the project"],"Failure information guides redesign.")
H('402.d.11.B',3,"A test protocol should describe the steps, the equipment, and the:","measurements to collect",["music","team colors","seating"],"Protocols make tests repeatable.")
H('402.d.11.B',4,"Using the same procedure for every trial makes results:","comparable",["random","secret","shorter"],"Consistent tests allow comparison.")
H('402.d.11.C',3,"Evaluating a prototype using data means looking at:","measurements rather than only opinions",["feelings only","rumors","guesses"],"Data supports evaluation.")
H('402.d.11.C',4,"A critique of a prototype should be:","specific and based on observations",["personal","vague","hostile"],"Useful feedback is specific.")
H('402.d.11.D',3,"A focus group is a small group of people who:","discuss a product and give feedback",["build the product","pay for the product","sell the product"],"Focus groups gather user opinion.")
H('402.d.11.D',4,"A user test where people try a prototype while the team watches is a:","usability test",["tax audit","production run","patent search"],"Usability tests show real use.")
H('402.d.11.E',3,"A success of a prototype is a feature that:","meets a stated criterion",["breaks","is ignored","is hidden"],"Successes match goals.")
H('402.d.11.E',4,"If a prototype holds 8 kg but the goal was 10 kg, this result is best described as:","a failure to meet one criterion",["a total success","irrelevant","a perfect design"],"Compare results with criteria.")
H('402.d.12.A',3,"A tool such as a failure mode analysis helps a team to:","find ways a design could fail",["pick colors","write slogans","sell products"],"Analysis predicts failure.")
H('402.d.12.A',4,"A fishbone (cause and effect) diagram helps a team to analyze:","the causes of a problem",["the budget only","the schedule only","the logo"],"Fishbone diagrams map causes.")
H('402.d.12.B',3,"After analyzing flaws, the team returns to earlier steps to:","improve and optimize the design",["quit","hide it","delete notes"],"Iterate for improvement.")
H('402.d.12.B',4,"Repeating a test after a design change allows the team to check whether the change:","improved performance",["was free","was popular","was legal"],"Retesting confirms impact.")
H('402.d.12.C',3,"Evaluating the impact of a solution means asking how well it:","solves the original problem",["looks","costs less","sells"],"Check against the problem.")
H('402.d.12.C',4,"A solution may also have impacts on people and the:","environment",["calendar","weather report","sports score"],"Consider side effects.")
H('402.d.13.A',3,"When presenting the experience of working on a design project, a student should share what the team:","did and learned",["ate","wore","bought"],"Reflect on the work.")
H('402.d.13.A',4,"A clear presentation of a project is organized with a beginning, middle, and:","end with conclusions",["random order","blank page","joke"],"Structure helps audiences.")
H('402.d.13.B',3,"Feedback on a team's use of the design process helps them to:","improve next time",["stop learning","lose track","hide results"],"Feedback supports growth.")
H('402.d.13.B',4,"Evaluating feedback means deciding which comments are:","useful and based on evidence",["loudest","rudest","first"],"Judge feedback quality.")
H('402.d.13.C',3,"A student who lists skills such as teamwork and communication gained from a project is doing a:","reflection",["repair","purchase","review of prices"],"Reflection captures learning.")
H('402.d.13.C',4,"Identifying areas for growth after a project means naming skills to:","practice and improve",["avoid","hide","forget"],"Growth areas set goals.")
H('403.d.1',3,"An engineer is asked to approve a part that fails a safety test. The ethical response is to:","refuse approval and report the failure",["approve it quietly","hide the result","change the test"],"Ethics require honesty about safety.")
H('403.d.1',4,"Engineering ethics research often cites the Challenger shuttle disaster, in which warnings about a faulty seal were:","overruled by schedule pressure",["fully heeded","never given","solved in time"],"Engineers warned but launch went ahead.")
H('403.d.2.A',3,"Applying an engineering design process to a real problem begins with:","defining the problem",["building at once","selling","ignoring users"],"Define first.")
H('403.d.2.A',4,"Stage-gate reviews in a design process make sure that a project:","meets criteria before moving on",["never changes","skips testing","ends early"],"Gates check readiness.")
H('403.d.2.B',3,"A project's scope describes:","what is and is not included in the work",["only the cost","the team uniforms","the color"],"Scope sets boundaries.")
H('403.d.2.B',4,"Scope creep happens when a project:","keeps adding work beyond the original plan",["shrinks","finishes early","has no budget"],"Uncontrolled additions cause delays.")
H('403.d.2.C',3,"A stakeholder is a person or group who:","is affected by or has an interest in the project",["pays only","builds only","designs only"],"Stakeholders include users and funders.")
H('403.d.2.C',4,"Consulting neighbors about a new factory's noise is an example of considering:","stakeholder concerns",["profit only","taxes only","marketing"],"Stakeholders influence decisions.")
H('403.d.2.D',3,"In engineering, failure can be useful because it:","teaches what must be improved",["is always a waste","ends learning","proves nothing"],"Learning from failure drives progress.")
H('403.d.2.D',4,"An engineer who studies why a test sample cracked is practicing:","failure analysis",["advertising","sales","scheduling"],"Failure analysis finds root causes.")
H('403.d.3.A',3,"The phases of a project include initiating, planning, executing, monitoring, and:","closing",["advertising","printing","hiding"],"Closing completes a project.")
H('403.d.3.A',4,"Monitoring a project during execution means:","comparing progress with the plan",["ignoring the plan","stopping work","hiding delays"],"Monitoring finds variances.")
H('403.d.3.B',3,"The project manager is responsible for:","coordinating the team and keeping the project on track",["building every part","buying lunch","painting"],"Managers coordinate.")
H('403.d.3.B',4,"A team member's role in a project is usually described in:","a defined set of responsibilities",["a random task list","a joke","a guess"],"Clear roles prevent overlap.")
H('403.d.3.C',3,"A Gantt chart is a tool that shows:","tasks along a timeline",["only budgets","blueprints","safety rules"],"Gantt charts schedule tasks.")
H('403.d.3.C',4,"A project management tool that lets team members track tasks and share files is:","project management software",["a drill press","a calculator only","a ruler"],"Software coordinates work.")
H('403.d.3.D',3,"A system for tracking documents helps a team to:","find the latest version of a file",["lose files","delete work","hide edits"],"Version control prevents confusion.")
H('403.d.3.D',4,"Naming files with version numbers and dates prevents:","working from outdated drawings",["saving","printing","backups"],"Clear versions avoid errors.")
H('403.d.3.E',3,"A deliverable is a:","product or document the team must provide",["tool","meeting","cost"],"Deliverables are outputs.")
H('403.d.3.E',4,"If a requirement changes late in a project, the team should assess the effect on the:","schedule and budget",["lunch menu","uniform","weather"],"Changes ripple.")
H('403.d.3.F',3,"A project budget includes the cost of materials, equipment, and:","labor",["luck","weather","hobbies"],"Budgets sum all costs.")
H('403.d.3.F',4,"If materials cost $400, equipment $250, and labor $600, the total budget is:","$1,250",["$1,150","$1,350","$850"],"400 + 250 + 600 = 1250.")
H('403.d.3.G',3,"Management of change (MOC) is a process used to:","review and approve changes before they are made",["avoid documentation","skip safety","block progress"],"MOC controls risk.")
H('403.d.3.G',4,"A change to a chemical plant's valve type should go through MOC because it may affect:","safety and operations",["lunch","uniforms","parking"],"Changes can create hazards.")
H('403.d.4.A',3,"Decomposing a problem means breaking it into:","smaller, manageable parts",["bigger parts","random pieces","nothing"],"Decomposition simplifies.")
H('403.d.4.A',4,"To plan an automatic watering system, a team might split the problem into sensing, deciding, and:","delivering water",["painting","naming","advertising"],"Each part is a subproblem.")
H('403.d.4.B',3,"A pattern in a sequence of numbers such as 2, 4, 6, 8 allows a programmer to:","predict the next number",["avoid math","delete data","stop the program"],"Patterns support prediction.")
H('403.d.4.B',4,"A repeating pattern in a manufacturing process can be automated using:","a loop in a program",["a typo","a comment","a variable name only"],"Repetition suggests loops.")
H('403.d.4.C',3,"Abstraction means focusing on the:","important details and ignoring the rest",["smallest detail","all details","none"],"Abstraction simplifies.")
H('403.d.4.C',4,"A function that is called by name without needing to know its internal steps is an example of:","abstraction",["error","loop","bug"],"Functions hide detail.")
H('403.d.4.D',3,"A flowchart is a visual way to plan:","the steps of a program",["a budget","a menu","a map"],"Flowcharts show logic.")
H('403.d.4.D',4,"In a flowchart, a diamond usually represents a:","decision",["start","process","document"],"Diamonds mean decisions.")
H('403.d.4.E',3,"Debugging is the process of:","finding and fixing errors in code",["writing comments","saving files","starting a program"],"Debugging fixes errors.")
H('403.d.4.E',4,"Adding print statements to see variable values while a program runs is a debugging technique called:","tracing",["compiling","copying","formatting"],"Tracing shows execution.")
H('403.d.4.F',3,"A loop is useful for:","repeating a set of instructions",["stopping a program","adding comments","naming files"],"Loops repeat.")
H('403.d.4.F',4,"To blink an LED ten times, a programmer would use a:","loop that repeats ten times",["comment","single command","variable only"],"Iteration saves code.")
H('403.d.4.G',3,"A Boolean expression evaluates to:","true or false",["any number","text","a picture"],"Boolean means true or false.")
H('403.d.4.G',4,"If x = 5, the expression x > 8 evaluates to:","false",["true","5","8"],"5 is not greater than 8.")
H('403.d.4.H',3,"A conditional statement tells a program to take an action only if:","a condition is true",["it is Friday","the file is large","the user smiles"],"Conditionals check conditions.")
H('403.d.4.H',4,"In 'if temperature > 30 then start fan', the fan starts only when the temperature is:","above 30",["below 30","exactly 0","unknown"],"The condition must hold.")
H('403.d.4.I',3,"A while loop repeats as long as its condition is:","true",["false","empty","commented"],"While means during truth.")
H('403.d.4.I',4,"A program loops 'while count < 3' and adds 1 to count each pass, starting from 0. The body runs:","3 times",["2 times","4 times","0 times"],"Runs for 0, 1, 2.")
H('403.d.4.J',3,"A scripting language such as Python is often used for:","quickly automating tasks",["building hardware","painting","drilling"],"Scripts automate.")
H('403.d.4.J',4,"A compiled language like C must be converted by a compiler before it:","can run as machine code",["can be typed","can be saved","can be printed"],"Compiling translates source code.")
H('403.d.4.K',3,"A code editor is used to:","write and edit program code",["print photos","play music","browse the web only"],"Editors help write code.")
H('403.d.4.K',4,"When a compiler reports an error on line 12, the programmer should:","examine line 12 and nearby lines",["restart the computer","delete the file","ignore the message"],"Errors point to the problem.")
H('403.d.5.A',3,"Programming and iterative design are similar because both involve:","testing and improving repeatedly",["one attempt","no changes","no testing"],"Both loop through test and revise.")
H('403.d.5.A',4,"Writing code, running it, finding a bug, and fixing it is a cycle that mirrors the design step of:","test and redesign",["define the problem","present the result","budget"],"Debug cycles are iteration.")
H('403.d.5.B',3,"Modifying existing code to add a new feature is easier if the original code has:","clear comments and names",["no names","no structure","errors"],"Readable code is easy to change.")
H('403.d.5.B',4,"After changing a line of code, the programmer should:","run the program to check the result",["assume it works","delete the old file","skip testing"],"Test after each change.")
H('403.d.5.C',3,"Block-based programming uses:","snap-together blocks instead of typed text",["only typed commands","no instructions","machine code"],"Blocks show logic visually.")
H('403.d.5.C',4,"A robot arm program written in text must follow the language's:","syntax",["color","sound","music"],"Syntax rules matter in text code.")
H('403.d.5.D',3,"A variable is a named place to store a:","value that can change",["fixed constant only","picture frame","file extension"],"Variables hold data.")
H('403.d.5.D',4,"A good variable name for a motor's speed is:","motor_speed",["x1","zzz","a"],"Descriptive names aid understanding.")
H('403.d.5.E',3,"The number 7 and the text 'seven' are different:","data types",["colors","sizes","files"],"Integer vs string.")
H('403.d.5.E',4,"A variable that holds 3.14 is best stored as a:","floating-point number",["string only","Boolean","character"],"Decimals use floats.")
H('403.d.5.F',3,"Comments in code are written to:","explain what the code does",["be run as commands","slow the program","hide errors"],"Comments help humans.")
H('403.d.5.F',4,"A comment that says 'convert inches to centimeters' next to a line of math helps future readers by explaining its:","purpose",["color","size","speed"],"Comments state intent.")
H('403.d.5.G',3,"The comparison operator '==' checks whether two values are:","equal",["different","larger","added"],"Double equals tests equality.")
H('403.d.5.G',4,"The expression 7 <= 7 evaluates to:","true",["false","7","error"],"Less than or equal includes equality.")
H('403.d.5.H',3,"A string is a data type for:","text",["whole numbers only","true/false only","sound only"],"Strings hold characters.")
H('403.d.5.H',4,"Sorting a list of names alphabetically works with the data type called:","string",["Boolean","float","integer only"],"Strings compare by character order.")
H('403.d.5.I',3,"User testing means having people:","try the program and give feedback",["read the code","ignore it","pay for it"],"Users reveal problems.")
H('403.d.5.I',4,"If several testers cannot find the start button, the programmer should:","redesign the interface to make it clearer",["blame the testers","remove the button","ignore the result"],"Feedback drives improvement.")
H('403.d.6.A',3,"A microcontroller can be programmed to read inputs and control:","outputs such as motors and lights",["only paper","only spreadsheets","only music"],"Controllers connect to devices.")
H('403.d.6.A',4,"Code that turns on a fan when a temperature sensor passes a limit is an example of:","process control",["word processing","game scoring","file storage"],"Input-process-output.")
H('403.d.6.B',3,"To test that an LED output works, a programmer writes code to:","turn it on and off",["delete it","paint it","bend it"],"Simple test of output.")
H('403.d.6.B',4,"If an LED does not light, one thing to check is whether it is connected with the correct:","polarity",["color","brand","size of the room"],"LEDs have + and - sides.")
H('403.d.6.C',3,"A push button is an example of an:","input device",["output device","power source","display"],"Buttons send signals in.")
H('403.d.6.C',4,"To verify an input device, a programmer can print its value to a:","serial monitor",["spreadsheet","calendar","map"],"Serial monitors display readings.")
H('403.d.6.D',3,"When a program does not work, a good first step is to:","read the error message",["unplug everything","start over","ignore it"],"Messages help.")
H('403.d.6.D',4,"Testing one small part of the code at a time to isolate a fault is called:","incremental testing",["random testing","skipping","guessing"],"Isolate the problem.")
H('403.d.6.E',3,"In a circuit, the ground connection provides a:","common reference and return path",["power source","sensor","display"],"Ground completes the loop.")
H('403.d.6.E',4,"Connecting a 9 V battery to a 5 V controller pin directly can:","damage the controller",["improve it","do nothing","speed it up"],"Wrong voltage can fry parts.")
H('403.d.6.F',3,"A script can be used to automate a repeated task such as:","logging sensor data to a file",["painting walls","sharpening tools","writing by hand"],"Scripts automate routine work.")
H('403.d.6.F',4,"An automatic lighting system that turns on at dusk uses a script along with a:","light sensor",["fan","paintbrush","wrench"],"Sensors trigger the script.")
H('403.d.7.A',3,"In the past, a thermostat used a bimetal strip to sense temperature, while today many use:","electronic sensors",["no sensors","candles","clocks"],"Sensor technology has changed.")
H('403.d.7.A',4,"Modern robots use sensors because they:","let a machine detect conditions in its environment",["stop all motion","remove power","replace programmers"],"Sensors give feedback.")
H('403.d.7.B',3,"To measure how far away an object is, a robot can use a(n):","ultrasonic distance sensor",["thermometer","microphone only","scale"],"Ultrasonic sensors measure range.")
H('403.d.7.B',4,"To detect whether a room is dark, an engineer would choose a(n):","photoresistor",["strain gauge","thermistor","pressure sensor"],"Photoresistors respond to light.")
H('403.d.7.C',3,"A sensor's specification sheet lists its operating voltage and its:","measurement range",["owner","color of the box","price of shipping"],"Specs determine suitability.")
H('403.d.7.C',4,"A sensor with a range of 2 to 400 cm cannot accurately detect an object that is:","1 cm away",["50 cm away","100 cm away","300 cm away"],"Outside the range is unreliable.")
H('403.d.7.D',3,"Choosing a sensor and explaining why shows the ability to:","defend a design decision with reasons",["guess","copy","delay"],"Justify choices.")
H('403.d.7.D',4,"For a greenhouse that must stay between 20 and 28 degrees Celsius, a good sensor choice is a:","temperature sensor with that range",["sound sensor","tilt switch","pressure mat"],"Match sensor to the variable.")
H('403.d.7.E',3,"Code that reads a sensor value many times per second is usually placed inside a:","loop",["comment","header","title"],"Loops sample repeatedly.")
H('403.d.7.E',4,"Averaging several sensor readings reduces the effect of:","random noise",["voltage","wires","code"],"Averaging smooths noise.")
H('403.d.7.F',3,"Sensor performance can be improved by calibrating the sensor to:","a known reference",["a guess","a color","a pen"],"Calibration reduces error.")
H('403.d.7.F',4,"If a sensor reading drifts from the true value, the engineer should:","recalibrate and retest it",["ignore it","delete the sensor","trust it more"],"Calibrate regularly.")
H('403.d.7.G',3,"The steps of connecting a sensor to a controller should be recorded in the:","engineering notebook",["menu","calendar","game"],"Documentation supports repeatability.")
H('403.d.7.G',4,"A wiring diagram in the notebook helps a teammate to:","rebuild the connection correctly",["skip testing","guess pins","avoid power"],"Diagrams guide wiring.")
H('403.d.8.A',3,"Automated machines in manufacturing are used to:","repeat tasks quickly and consistently",["avoid precision","reduce safety","slow output"],"Automation improves consistency.")
H('403.d.8.A',4,"A CNC machine follows a program to:","cut parts to exact specifications",["draw sketches by itself","replace engineers","paint walls"],"CNC machines follow code.")
H('403.d.8.B',3,"A career in automation may require a degree, a certificate, or:","apprenticeship training",["no skills","no study","a hobby"],"Pathways vary.")
H('403.d.8.B',4,"A person who maintains and repairs robotic equipment is commonly called a:","technician",["accountant","chef","actor"],"Technicians maintain equipment.")
H('403.d.8.C',3,"Engineers usually design systems, while technicians usually:","install, test, and maintain them",["never touch equipment","only sell them","only approve budgets"],"Roles differ.")
H('403.d.8.C',4,"A technologist often works at a level between:","engineer and technician",["child and adult","teacher and student","manager and customer"],"Technologists bridge roles.")
H('403.d.8.D',3,"A robot cell in a factory is surrounded by guards to protect workers from:","moving machinery",["noise only","cold","paper"],"Guards prevent contact.")
H('403.d.8.D',4,"An ethical concern about automation is that it may:","change or eliminate some jobs",["raise gravity","stop all learning","remove math"],"Societal impact matters.")
H('403.d.8.E',3,"Converting a hand-operated press to automatic requires adding sensors, actuators, and:","a controller with code",["a longer handle","more paint","fewer parts"],"Automation needs control.")
H('403.d.8.E',4,"A limit switch on an automated press tells the controller that the part is:","in position",["too heavy","wet","late"],"Switches give position feedback.")
H('403.d.9.A',3,"Lab safety rules are given by the instructor so that students can:","work without injury",["finish early","avoid thinking","skip steps"],"Safety is a priority.")
H('403.d.9.A',4,"Before powering a circuit, students should have the instructor:","check the wiring",["leave","sign the lunch form","paint it"],"A check prevents shorts.")
H('403.d.9.B',3,"Hazardous materials are grouped by:","the type of danger they present",["color only","price","size of container"],"Classes include flammable and corrosive.")
H('403.d.9.B',4,"A label with a flame symbol marks a material that is:","flammable",["radioactive","cold","edible"],"Symbols show hazards.")
H('403.d.9.C',3,"Used solder and chemicals are disposed of:","according to posted procedures",["in any bin","down the sink","anywhere"],"Follow waste rules.")
H('403.d.9.C',4,"Lead-free solder scraps and used batteries are placed in:","designated recycling or waste containers",["the regular trash","the drain","a pocket"],"Dispose properly.")
H('403.d.9.D',3,"Improperly maintained tools can cause:","injuries and poor-quality work",["better results","safer shops","savings only"],"Maintenance protects workers.")
H('403.d.9.D',4,"A dull saw blade is dangerous because it requires more force and may:","slip or bind",["cut itself","become sharper","shine"],"Dull tools slip.")
H('403.d.9.E',3,"A digital caliper is used to measure:","small dimensions precisely",["room size","weight","temperature"],"Calipers give precise length.")
H('403.d.9.E',4,"A multimeter set to measure voltage is connected to a circuit:","in parallel across the component",["in series","backwards on purpose","only when unpowered"],"Voltage is measured across.")
H('403.d.9.F',3,"A designer reviewing a circuit for quality and reliability looks for:","weak points that could fail",["decorations","logos","paint"],"Review for risks.")
H('403.d.9.F',4,"Using a resistor with an LED is a design choice that improves:","reliability by limiting current",["brightness always","color","price"],"Resistors protect LEDs.")
H('403.d.9.G',3,"Regulations from OSHA exist to protect workers' health and:","safety",["pay","hours","hobbies"],"OSHA sets rules.")
H('403.d.9.G',4,"A company that follows industry standards and regulations is more likely to have products that are:","safe and accepted by customers",["unsafe","banned","untested"],"Compliance builds trust.")

H('401.d.1.G',4,"A wind-tunnel test of a small airplane shape before building the real plane is an example of using a:","physical scale model",["final product","hypothesis only","published law"],"Scale models test performance cheaply.")
H('401.d.1.H',4,"A statement like 'objects in free fall near Earth accelerate at about 9.8 m/s²' is best classified as a:","law describing a regular pattern",["guess","personal opinion","unrelated claim"],"Laws summarize observed regularities.")
H('401.d.9.D',4,"Household outlets are wired in parallel so that each appliance receives the same:","voltage",["current","resistance","power"],"Parallel branches share voltage.")
H('401.d.9.E',4,"A 6 ohm resistor carries a current of 2 A. The voltage across it is:","12 V",["3 V","8 V","4 V"],"V = IR = 12.")
H('401.d.11.B',4,"A metal spoon left in a hot cup of soup feels hot at the handle because heat moves through the metal by:","conduction",["radiation only","convection only","fission"],"Heat travels through solids by conduction.")

